/**
 * mkdirp -> fs.mkdirSync(path, { recursive: true }) (JavaScript, native, file system effects).
 *
 * Why this pair: the function is all side effects, so the séance compares what ends up on disk
 * (the tree, the modes) as well as the answer. Both sides run in identical temporary directories.
 *
 * Versions (round 4b). mkdirp changed its shape across majors, and the séance follows the version in use:
 *   - 0.5.x: callback API, `mkdirp(dir, [opts], cb)` and `mkdirp.sync`; answers `null` when every directory
 *     existed. The recipe covers it: the replacement takes a callback and answers `null`.
 *   - 1.x, 2.x: the default export is the function (promise API, `.sync`); answers `undefined`.
 *   - 3.x: no default export, named exports `mkdirp`, `mkdirpSync`, `sync`; same answers as 1.x.
 * The test file imports the module as a namespace and picks the function that exists, so one file runs
 * on all of them. The legacy (0.x) and modern (1.x and later) flavours differ in the replacement and in
 * the second test (callback form against promise form).
 */

import type { KnownDifference, SeanceBundle, SeanceFile } from '../../types.js';
import { callsNote, jsProjectCalls } from '../examples.js';
import { renderReadme } from '../readme.js';
import { makeBundle, type Mutant, type Recipe, type RecipeContext } from '../recipe.js';
import { TESTED_VERSIONS } from '../tested-versions.js';
import { majorInUse, oldVersionsFor } from '../versions.js';

const DIR = 'seance/mkdirp';

export const MKDIRP_KNOWN: KnownDifference[] = [
  {
    input: 'mkdirp.sync("")',
    old: 'undefined (the empty path means the current directory, which exists)',
    naive: 'throws ENOENT',
    handled: 'Reproduced: the replacement resolves the path first, like mkdirp.',
  },
  {
    input: 'mkdirp.sync(dir, 0o700)',
    old: 'creates the directories with mode 0o700 (a number is the mode)',
    naive: 'a number is not a valid option: the mode is ignored',
    handled: 'Reproduced: the replacement turns a number or { mode } into the mode option.',
  },
];

/** mkdirp 0.x is the callback flavour; anything else (or an unknown version) is the modern one. */
function isLegacy(ctx: RecipeContext | undefined): boolean {
  const dep = ctx?.diagnosis?.dependency;
  return dep !== undefined && majorInUse(dep) === 0;
}

function replacementSource(legacy: boolean, mutate?: 'last-directory'): string {
  const answer = (expr: string): string =>
    mutate === 'last-directory'
      ? `{ const made = ${expr}; return made === undefined ? ${legacy ? 'null' : 'made'} : path.resolve(dir); }`
      : legacy
        ? `{ const made = ${expr}; return made === undefined ? null : made; }`
        : `{ return ${expr}; }`;
  const head = [
    '// Replacement for mkdirp. Generated by Necromancer (recipe "mkdirp").',
    legacy
      ? '// For mkdirp 0.5 (callback API). Dependency-free: fs.mkdir with { recursive: true }.'
      : '// Dependency-free: fs.mkdir with { recursive: true }.',
    legacy
      ? '// Use mkdirpSync where you used mkdirp.sync, and mkdirp(dir, [opts], cb) where you used mkdirp.'
      : '// Use mkdirpSync where you used mkdirp.sync, and mkdirp where you used mkdirp (it returns a promise).',
    "import fs from 'node:fs';",
    "import path from 'node:path';",
    '',
    '// mkdirp takes a mode number, a mode string or { mode }.',
    "const modeOf = (opts) => (typeof opts === 'number' || typeof opts === 'string' ? opts : opts && opts.mode);",
    'const optionsFor = (opts) => {',
    '  const mode = modeOf(opts);',
    '  return mode === undefined ? { recursive: true } : { recursive: true, mode };',
    '};',
    '',
    '// mkdirp resolves the path first: "" means the current directory, relative paths use the cwd.',
    legacy
      ? '// Returns the first directory that was created, or null when all of them existed (mkdirp 0.5).'
      : '// Returns the first directory that was created, or undefined when all of them existed.',
  ];
  if (legacy) {
    return [
      ...head,
      'export function mkdirpSync(dir, opts) {',
      `  ${answer('fs.mkdirSync(path.resolve(dir), optionsFor(opts))')}`,
      '}',
      '',
      '// mkdirp 0.5: mkdirp(dir, [opts], [cb]); cb(err, made) is called later, never in the same tick.',
      'export function mkdirp(dir, opts, cb) {',
      "  if (typeof opts === 'function') { cb = opts; opts = undefined; }",
      '  const target = path.resolve(dir);',
      '  fs.promises.mkdir(target, optionsFor(opts)).then(',
      '    (made) => { if (cb) cb(null, made === undefined ? null : ' +
        (mutate === 'last-directory' ? 'path.resolve(dir)' : 'made') +
        '); },',
      '    (err) => { if (cb) cb(err); },',
      '  );',
      '}',
      '',
    ].join('\n');
  }
  return [
    ...head,
    'export function mkdirpSync(dir, opts) {',
    `  ${answer('fs.mkdirSync(path.resolve(dir), optionsFor(opts))')}`,
    '}',
    '',
    'export async function mkdirp(dir, opts) {',
    mutate === 'last-directory'
      ? '  const made = await fs.promises.mkdir(path.resolve(dir), optionsFor(opts)); return made === undefined ? made : path.resolve(dir);'
      : '  return fs.promises.mkdir(path.resolve(dir), optionsFor(opts));',
    '}',
    '',
  ].join('\n');
}

function testSource(projectCalls: string[], legacy: boolean, tested: string[]): string {
  const none = legacy ? 'null' : 'undefined';
  return [
    '// Séance: mkdirp -> fs.mkdir recursive. Generated by Necromancer (recipe "mkdirp").',
    '// Run: npx vitest run seance/mkdirp',
    '//',
    '// For each generated situation (existing folders and files, a target path, an optional mode) the',
    '// séance builds the same starting tree twice, calls mkdirp in one and the replacement in the',
    '// other, and compares: the returned path (relative to the tree), the error class and code, and',
    '// the whole resulting tree (names, kinds, folder modes). Compared after the umask is applied.',
    legacy
      ? '// Written for mkdirp 0.5 (callback API; answers null when nothing was created).'
      : '// Written for mkdirp 1.x, 2.x and 3.x (promise API; answers undefined when nothing was created).',
    "import fs from 'node:fs';",
    "import os from 'node:os';",
    "import path from 'node:path';",
    "import { createRequire } from 'node:module';",
    "import { describe, it, expect, afterAll } from 'vitest';",
    "import fc from 'fast-check';",
    "import * as mkdirpModule from 'mkdirp';",
    "import { mkdirpSync, mkdirp as mkdirpNew } from './replacement.mjs';",
    '',
    '// mkdirp 0.5, 1.x and 2.x export the function as the default export; mkdirp 3.x has named exports only.',
    'const mkdirpOldAsync = mkdirpModule.default ?? mkdirpModule.mkdirp;',
    'const mkdirpOldSync = mkdirpOldAsync.sync ?? mkdirpModule.sync ?? mkdirpModule.mkdirpSync;',
    `const NONE = ${none}; // what mkdirp answers when every directory already existed`,
    '',
    '// The version of mkdirp that is installed, and the versions this séance was run against.',
    `const TESTED = ${JSON.stringify(tested)};`,
    'function installedVersion() {',
    '  try {',
    "    let dir = path.dirname(createRequire(import.meta.url).resolve('mkdirp'));",
    '    for (let i = 0; i < 6; i++) {',
    "      const file = path.join(dir, 'package.json');",
    '      if (fs.existsSync(file)) {',
    "        const json = JSON.parse(fs.readFileSync(file, 'utf8'));",
    "        if (json.name === 'mkdirp') return json.version;",
    '      }',
    '      dir = path.dirname(dir);',
    '    }',
    '  } catch { /* the version is only reported */ }',
    '  return undefined;',
    '}',
    'const INSTALLED = installedVersion();',
    'if (INSTALLED && !TESTED.includes(INSTALLED)) {',
    "  console.warn('mkdirp ' + INSTALLED + ' is not one of the versions this séance was run against (' + TESTED.join(', ') + '): a failure may not be the replacement\\'s fault.');",
    '}',
    '',
    "const root = fs.mkdtempSync(path.join(os.tmpdir(), 'seance-mkdirp-'));",
    'afterAll(() => fs.rmSync(root, { recursive: true, force: true }));',
    'let counter = 0;',
    '',
    '// The starting tree: folders and files, as lists of path segments.',
    "const name = fc.constantFrom('a', 'b', 'c', 'x y', '\\u00e9', 'd.e');",
    'const segs = fc.array(name, { minLength: 1, maxLength: 3 });',
    "const entry = fc.record({ kind: fc.constantFrom('dir', 'file'), segs });",
    'const tree = fc.array(entry, { maxLength: 4 });',
    "// A target is a list of segments; '' and '.' produce // and /./ inside the path.",
    "const targetSegs = fc.array(fc.oneof(name, fc.constantFrom('', '.')), { minLength: 1, maxLength: 5 });",
    "const trailing = fc.constantFrom('', '/');",
    'const mode = fc.constantFrom(undefined, 0o700, 0o755, { mode: 0o750 }, { mode: 0o700 });',
    '',
    'function build(base, entries) {',
    '  fs.mkdirSync(base, { recursive: true });',
    '  for (const e of entries) {',
    '    const p = path.join(base, ...e.segs);',
    "    try { if (e.kind === 'dir') fs.mkdirSync(p, { recursive: true }); else { fs.mkdirSync(path.dirname(p), { recursive: true }); fs.writeFileSync(p, 'x'); } } catch { /* a file may be in the way: same in both trees */ }",
    '  }',
    '}',
    '',
    'function snapshot(base) {',
    '  const out = [];',
    '  const walk = (dir) => {',
    '    for (const n of fs.readdirSync(dir).sort()) {',
    '      const p = path.join(dir, n);',
    '      const st = fs.statSync(p);',
    "      out.push([path.relative(base, p), st.isDirectory() ? 'dir' : 'file', st.isDirectory() ? st.mode & 0o777 : null]);",
    '      if (st.isDirectory()) walk(p);',
    '    }',
    '  };',
    '  walk(base);',
    '  return out;',
    '}',
    '',
    "const rel = (base, made) => (typeof made === 'string' ? path.relative(base, made) : made);",
    'const errorOf = (e) => ({ error: e && e.constructor ? e.constructor.name : typeof e, code: e && e.code });',
    '',
    'function sideBySide(entries, target, opts, runOld, runNew) {',
    '  const id = ++counter;',
    "  const a = path.join(root, id + 'a');",
    "  const b = path.join(root, id + 'b');",
    '  build(a, entries);',
    '  build(b, entries);',
    '  const one = (base, fn) => { try { return { ok: true, made: rel(base, fn(path.join(base, target), opts)) }; } catch (e) { return { ok: false, ...errorOf(e) }; } };',
    '  const x = one(a, runOld);',
    '  const y = one(b, runNew);',
    '  return [{ ...x, tree: snapshot(a) }, { ...y, tree: snapshot(b) }];',
    '}',
    '',
    "describe('seance: mkdirp -> fs.mkdir recursive', () => {",
    "  it('the installed mkdirp is of the family this séance was written for', () => {",
    "    const major = Number(String(INSTALLED ?? '').split('.')[0]);",
    '    if (Number.isNaN(major)) return; // the version could not be read: nothing to check',
    legacy
      ? "    expect(major, 'this séance was written for mkdirp 0.5; mkdirp ' + INSTALLED + ' is installed: generate it again for that version').toBe(0);"
      : "    expect(major >= 1, 'this séance was written for mkdirp 1.x to 3.x; mkdirp ' + INSTALLED + ' is installed: generate it again for that version').toBe(true);",
    '  });',
    '',
    "  it('mkdirp.sync and mkdirpSync leave the same tree and return the same path', () => {",
    '    fc.assert(',
    '      fc.property(tree, targetSegs, trailing, mode, (entries, t, slash, m) => {',
    "        const target = t.join('/') + slash;",
    '        const [x, y] = sideBySide(entries, target, m, (p, o) => mkdirpOldSync(p, o), (p, o) => mkdirpSync(p, o));',
    '        expect(y).toEqual(x);',
    '      }),',
    '      { numRuns: 300 },',
    '    );',
    '  });',
    '',
    ...(legacy
      ? [
          "  it('mkdirp (callback) and the replacement leave the same tree and call back with the same path', async () => {",
          '    await fc.assert(',
          '      fc.asyncProperty(tree, targetSegs, mode, async (entries, t, m) => {',
          "        const target = t.join('/');",
          '        const id = ++counter;',
          "        const a = path.join(root, id + 'a'); const b = path.join(root, id + 'b');",
          '        build(a, entries); build(b, entries);',
          '        const one = (base, fn) => new Promise((resolve) => {',
          '          const done = (err, made) => resolve(err ? { ok: false, ...errorOf(err) } : { ok: true, made: rel(base, made) });',
          '          try { fn(path.join(base, target), m, done); } catch (e) { resolve({ ok: false, ...errorOf(e) }); }',
          '        });',
          '        const x = await one(a, (p, o, cb) => mkdirpOldAsync(p, o, cb));',
          '        const y = await one(b, (p, o, cb) => mkdirpNew(p, o, cb));',
          '        expect({ ...y, tree: snapshot(b) }).toEqual({ ...x, tree: snapshot(a) });',
          '      }),',
          '      { numRuns: 100 },',
          '    );',
          '  });',
        ]
      : [
          "  it('mkdirp (promise) and the async replacement leave the same tree and return the same path', async () => {",
          '    await fc.assert(',
          '      fc.asyncProperty(tree, targetSegs, mode, async (entries, t, m) => {',
          "        const target = t.join('/');",
          '        const id = ++counter;',
          "        const a = path.join(root, id + 'a'); const b = path.join(root, id + 'b');",
          '        build(a, entries); build(b, entries);',
          '        const one = async (base, fn) => { try { return { ok: true, made: rel(base, await fn(path.join(base, target), m)) }; } catch (e) { return { ok: false, ...errorOf(e) }; } };',
          '        const x = await one(a, (p, o) => mkdirpOldAsync(p, o));',
          '        const y = await one(b, (p, o) => mkdirpNew(p, o));',
          '        expect({ ...y, tree: snapshot(b) }).toEqual({ ...x, tree: snapshot(a) });',
          '      }),',
          '      { numRuns: 100 },',
          '    );',
          '  });',
        ]),
    '',
    "  it('wrong argument types fail with the same error class', () => {",
    '    fc.assert(',
    '      fc.property(fc.constantFrom(null, undefined, 1, {}, [], true), (bad) => {',
    '        const run = (fn) => { try { fn(bad); return { ok: true }; } catch (e) { return { ok: false, error: e && e.constructor ? e.constructor.name : typeof e }; } };',
    '        expect(run((p) => mkdirpSync(p))).toEqual(run((p) => mkdirpOldSync(p)));',
    '      }),',
    '    );',
    '  });',
    '',
    "  it('the empty path means the current directory, as in mkdirp', () => {",
    '    expect(mkdirpOldSync("")).toBe(NONE);',
    '    expect(mkdirpSync("")).toBe(NONE);',
    '    expect(() => fs.mkdirSync("", { recursive: true })).toThrow(); // the naive call',
    '  });',
    '',
    "  it('a mode given as a number is applied; the naive call ignores it', () => {",
    "    const a = path.join(root, 'mode-old/x/y'); const b = path.join(root, 'mode-new/x/y'); const c = path.join(root, 'mode-naive/x/y');",
    '    mkdirpOldSync(a, 0o700); mkdirpSync(b, 0o700); fs.mkdirSync(c, { recursive: true, mode: undefined });',
    '    expect(fs.statSync(b).mode & 0o777).toBe(fs.statSync(a).mode & 0o777);',
    '    expect(fs.statSync(a).mode & 0o777).toBe(0o700 & ~process.umask());',
    '  });',
    '',
    ...projectCalls,
    "  it('the replacement answers like mkdirp on the paths this project uses', () => {",
    '    for (const [p] of projectCalls) {',
    "      if (typeof p !== 'string') continue;",
    '      const rootOld = path.join(root, "own-old"); const rootNew = path.join(root, "own-new");',
    '      fs.mkdirSync(rootOld, { recursive: true }); fs.mkdirSync(rootNew, { recursive: true });',
    '      const rel2 = p.replace(/^\\/+/, "");',
    '      const x = mkdirpOldSync(path.join(rootOld, rel2)); const y = mkdirpSync(path.join(rootNew, rel2));',
    '      expect(rel(rootNew, y)).toEqual(rel(rootOld, x));',
    '    }',
    '  });',
    '});',
    '',
  ].join('\n');
}

function build(ctx: RecipeContext): SeanceBundle {
  const legacy = isLegacy(ctx);
  const pick = (m: string): boolean => m === 'sync' || m === 'default';
  const dep = ctx?.diagnosis?.dependency;
  const oldVersions = oldVersionsFor('mkdirp', {
    ecosystem: 'npm',
    name: 'mkdirp',
    spec: dep?.spec ?? '',
    ...(dep?.resolved ? { resolved: dep.resolved } : {}),
  });
  const tested = TESTED_VERSIONS['mkdirp']?.pass ?? [];
  const files: SeanceFile[] = [
    {
      path: `${DIR}/seance.test.mjs`,
      content: testSource(jsProjectCalls(ctx.usage, pick, 'projectCalls', '  '), legacy, tested),
      role: 'test',
    },
    { path: `${DIR}/replacement.mjs`, content: replacementSource(legacy), role: 'replacement' },
  ];
  const compares = [
    'The returned path (relative to the test tree) or the error class and code; and the whole resulting tree: names, file or folder, folder modes.',
    'Both sides start from identical generated trees (folders, files that may be in the way) and the same target: nested names, "." and empty segments, trailing slash, with and without a mode.',
    legacy
      ? 'Async: the callback form of mkdirp 0.5 against the callback replacement (the answer is null when nothing was created). Not covered: custom fs implementations passed as opts.fs.'
      : 'Async: the promise form of mkdirp against the async replacement. Not covered: custom fs implementations passed as opts.fs. For mkdirp 0.5 (callback API) generate the séance again with that version in the diagnosis.',
    callsNote(ctx.usage, pick),
    `Versions: ${oldVersions.note}`,
  ];
  const install = ['npm install --save-dev vitest fast-check'];
  const run = 'npx vitest run seance/mkdirp';
  files.push({
    path: `${DIR}/README.md`,
    role: 'readme',
    content: renderReadme({
      title: 'mkdirp to fs.mkdir recursive',
      recipe: 'mkdirp',
      files: [
        {
          path: `${DIR}/seance.test.mjs`,
          what: 'the differential property test (compares files on disk)',
        },
        {
          path: `${DIR}/replacement.mjs`,
          what: legacy
            ? 'mkdirpSync and mkdirp(dir, opts, cb) with the answers of mkdirp 0.5'
            : 'mkdirpSync and mkdirp with the old answers',
        },
      ],
      install,
      run,
      compares,
      known: MKDIRP_KNOWN,
      versions: oldVersions.note,
    }),
  });
  return makeBundle({
    language: 'javascript',
    recipe: 'mkdirp',
    title: 'mkdirp to fs.mkdir recursive',
    files,
    install,
    run,
    compares,
    knownDifferences: MKDIRP_KNOWN,
    members: ['default', 'sync'],
    oldVersions,
  });
}

function mutants(ctx: RecipeContext): Mutant[] {
  const legacy = isLegacy(ctx);
  const path = `${DIR}/replacement.mjs`;
  return [
    {
      id: 'naive-mkdir-recursive',
      description: 'calls fs.mkdirSync(dir, { recursive: true }) and ignores the mode',
      files: [
        {
          path,
          role: 'replacement',
          content: legacy
            ? [
                "import fs from 'node:fs';",
                'export function mkdirpSync(dir) { return fs.mkdirSync(dir, { recursive: true }); }',
                'export function mkdirp(dir, opts, cb) {',
                "  if (typeof opts === 'function') cb = opts;",
                '  fs.promises.mkdir(dir, { recursive: true }).then((m) => cb && cb(null, m), (e) => cb && cb(e));',
                '}',
                '',
              ].join('\n')
            : [
                "import fs from 'node:fs';",
                'export function mkdirpSync(dir) { return fs.mkdirSync(dir, { recursive: true }); }',
                'export async function mkdirp(dir) { return fs.promises.mkdir(dir, { recursive: true }); }',
                '',
              ].join('\n'),
        },
      ],
    },
    {
      id: 'returns-last-directory',
      description: 'returns the last directory instead of the first one created',
      files: [{ path, role: 'replacement', content: replacementSource(legacy, 'last-directory') }],
    },
  ];
}

export const mkdirpRecipe: Recipe = {
  id: 'mkdirp',
  language: 'javascript',
  ecosystem: 'npm',
  old: 'mkdirp',
  successors: ['fs.mkdir', 'fs.mkdirSync', 'fs.promises.mkdir'],
  why: 'A function that is all side effects: the séance compares what ends up on disk, not just a return value.',
  build,
  mutants,
};
